 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            minr = min(x for x, _ in cells)
            minc = min(y for _, y in cells)
            shape = frozenset((x-minr, y-minc) for x, y in cells)
            components.setdefault(color, []).append((cells, shape))
    # Recolor each color-1 object to the color of an exactly matching object.
    by_shape = {}
    for color, objs in components.items():
        if color != 1:
            for cells, shape in objs:
                by_shape.setdefault(shape, []).append(color)
    for cells, shape in components.get(1, []):
        matches = by_shape.get(shape, [])
        if matches:
            target = matches[0]
            for r, c in cells:
                out[r][c] = target
    return out


if __name__ == '__main__':
